    <style>
      body {
        font-family: Arial, sans-serif;
      }
    </style>
  </head>
  <body>
    <h1>Pendulum Simulator</h1>
    <input type="number" id="initial-angle" value="30" />
    <button id="release">Release</button>
    <canvas id="canvas" width="600" height="400"></canvas>
    <script>
      let canvas = document.getElementById('canvas');
      let ctx = canvas.getContext('2d');
      let initialAngle = 30;
      let release = false;
      let theta = 0;
      let omega = 0;
      let g = 0.981; // gravity in m/s^2
      let l = 100; // pendulum length in pixels
      let t = 0;
      let dt = 0.01;
      let også = 1; // angular frequency

      function drawPendulum() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.beginPath();
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 2;
        ctx.moveTo(canvas.width / 2, canvas.height / 2);
        ctx.lineTo(canvas.width / 2 + l * Math.sin(theta), canvas.height / 2 - l * Math.cos(theta));
        ctx.stroke();
      }

